/* ===== END ORIGINAL ENGINE ===== */

// Ratings the original form stored as 1-4 per classroom.
const RATING_FIELDS = [
  'pedagogyDesign', 'pedagogyAgency', 'pedagogyInclusivity',
  'platformsScheduling', 'platformsIntegration', 'platformsEportal',
  'teacherConfidence', 'learnerConfidence', 'relationalSafety',
  'classroomCollab', 'cyberWellness',
];
const TEXT_FIELDS = [
  'teacherName', 'subjectObserved', 'gradeObserved', 'lessonTopic', 'learnersCount',
  'toolsUsed', 'artifactVerified', 'teacherUpskilling', 'advisorSupport',
  'generalComments', 'teacherAction', 'learnerAction',
];
const FLAG_FIELDS = ['smartboardObserved', 'tabletsObserved', 'labObserved', 'internetObserved', 'offlineObserved'];

const toSnake = (s) => s.replace(/[A-Z]/g, (c) => '_' + c.toLowerCase());
const pick = (row, camel) => {
  if (row[camel] !== undefined && row[camel] !== null) return row[camel];
  const snake = toSnake(camel);
  return row[snake] !== undefined && row[snake] !== null ? row[snake] : undefined;
};

/**
 * Accepts a Supabase classroom_observations row (snake_case) OR the
 * original camelCase shape, and returns the camelCase shape the engine
 * expects. Missing ratings default to 1, exactly as the original did.
 */
export function normalizeClassroomRow(row) {
  const r = row || {};
  const out = { id: r.id };
  TEXT_FIELDS.forEach((f) => {
    const v = pick(r, f);
    out[f] = v === undefined || v === null ? '' : String(v);
  });
  FLAG_FIELDS.forEach((f) => {
    out[f] = !!pick(r, f);
  });
  RATING_FIELDS.forEach((f) => {
    const n = Number(pick(r, f));
    out[f] = Number.isFinite(n) && n > 0 ? n : 1;
  });
  return out;
}

/**
 * @param {{schoolName?:string, district?:string, visitDate?:string, advisorName?:string}} header
 * @param {object} classroomRow  one classroom_observations row
 */
export function buildClassroomAnalysis(header, classroomRow) {
  const cls = normalizeClassroomRow(classroomRow);
  const assessment = { classrooms: [cls], teacherName: cls.teacherName };
  const result = Ub(header || {}, assessment);

  // The original app stored grade as a bare number ("8") and the engine
  // prepends "Grade " for display. This app's form stores the full label
  // ("Grade 8", "Grade R", "Multi-Grade"), which would render as
  // "Grade Grade 8". Show the stored label as-is instead. (The engine's own
  // grade parsing still receives the raw value and copes with "Grade 8".)
  if (cls.gradeObserved && cls.gradeObserved.trim() !== '') {
    result.fieldEvidenceSummary.grade = cls.gradeObserved.trim();
  }
  return { ...result, classroom: cls };
}
